import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DC2M1AAK.js";const n="/marg/assets/playground.DXaaQW8a.gif",u=JSON.parse(`{"title":"Marg — agents that finish the job","description":"","frontmatter":{"layout":"home","title":"Marg — agents that finish the job","hero":{"name":"Marg","text":"Agents that finish the job.","tagline":"The open-source Agent Development Kit for conversational agents that complete a transaction. The runtime owns the moments that must be right; the model owns the conversation. TypeScript, MCP, any model.","actions":[{"theme":"brand","text":"Get started","link":"/get-started/"},{"theme":"alt","text":"Try the playground","link":"https://marg-playground.onrender.com"},{"theme":"alt","text":"GitHub","link":"https://github.com/marg-adk/marg"}]},"features":[{"title":"The runtime owns the moments that must be right","details":"Forms, pickers, option chips, the confirmation summary and the create gate are drawn and read by the runtime, in code, by the whole message. A model that skips a question, invents a value, or reads \\"yes but change the title\\" as a yes cannot do so here.","link":"/build/pattern","linkText":"The pattern"},{"title":"Typed decisions, not prose","details":"Which domain, is this a yes, which option, is it safe to write — asked as choice / noul / score questions and answered by rules first, a decision model second, an LLM with logprobs last, with calibrated confidence.","link":"/components/decisions","linkText":"Verdict"},{"title":"Evals as the ratchet, offline","details":"Scripted conversations against a writes-off gateway with deterministic checks, a mock model that plays the model's part, flake classification, a gate that runs in CI with no key and no network.","link":"/build/evals","linkText":"Evals"},{"title":"A production spine","details":"Identity that fails closed, owner checks, rate limits, usage caps, pass-through metering, OpenTelemetry in the GenAI conventions, dashboards and alerts as code, graceful deploys, a widget people use on a phone.","link":"/run/production-checklist","linkText":"Going to production"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),r={name:"index.md"};function o(d,e,l,h,p,c){return a(),s("div",null,[...e[0]||(e[0]=[i("",17)])])}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
